(require '[clojure.string :as str] '[clojure.edn :as edn])
(def project (System/getenv "KOTOBASE_ORACLE_ROOT"))
(load-string (first (str/split (slurp (str project "/oracle/awai-174/governed_linked_registry_memory.clj")) #"\(let \[before \(memory/snapshot memory-backend\)" 2)))
(require '[kotobase.storage.core :as storage] '[awai.fs.car :as car])
(import '[java.security MessageDigest] '[java.util Random Arrays])
(def base (System/getenv "LINKED_GOVERNED_BASE"))
(def backend (fb/open-backend (str base "/store") (str base "/stage") tool))
(def database (core/open {:storage backend :encrypt-fn identity :decrypt-fn identity :blind-fn pr-str :visible? (constantly true)}))
(def ref-cid (:cid (storage/-read-ref backend "linked-governed")))
(assert (string? ref-cid))
(def snapshot (core/at-cid database ref-cid))
(def headers (core/q snapshot [nil "kotobase.causal/format" "kotobase.causal-record.v1"]))
(assert (= 1 (count headers)))
(def ids {:commit ref-cid :cid (:s (first headers))})
(def records (:receipt/records (causal/receipt-at database (:commit ids) (:cid ids))))
(assert (= (:commit ids) (:cid (storage/-read-ref backend "linked-governed"))))
(assert (= 3 (count records))) (assert (= authority-receipt (second records)))
(assert (true? (link/verify! {:link (nth records 2) :request (assoc request :nonce "linked-governed-forest-01") :query query :execution-receipt (first records) :authority-receipt (second records) :value-cid id/value-cid :verify (:verify opts)})))
(assert (try (link/verify! {:link (nth records 2) :request (assoc request :nonce "other") :query query :execution-receipt (first records) :authority-receipt (second records) :value-cid id/value-cid :verify (:verify opts)}) false (catch Exception _ true)))
(assert (try (link/verify! {:link (nth records 2) :request (assoc request :nonce "linked-governed-forest-01") :query query :execution-receipt (first records) :authority-receipt (second records) :value-cid id/value-cid :verify (constantly false)}) false (catch Exception _ true)))
(def rng (Random. 174532))
(dotimes [_ 2] (let [b (byte-array (* 600 1024)) _ (.nextBytes rng b) d (mapv #(bit-and 255 %) (.digest (MessageDigest/getInstance "SHA-256") b)) cid (car/cid-str (car/cid-bytes car/codec-raw d))] (assert (Arrays/equals ^bytes b ^bytes (storage/get-block backend cid)))))
(prn {:marker :unused :ref :verified :receipt-discovery :unique :records 3 :link :verified :wrong-request :rejected :bad-signature :rejected :attachments :verified :pass true})
(shutdown-agents)
